#include <string>
#include <iostream>

int main() {
    std::string s1("Short string");  // May use SSO if short enough.
    std::string s2("This is a much longer string that might require heap allocation");

    s1.assign(s2, 0, 10);  // Assigns the first 10 characters of s2 to s1
    std::cout << "After assign: " << s1 << std::endl;  // Outputs the result
    return 0;
}
